import {createInterface} from 'node:readline';
export function handleMcp(message){if(message.method==='initialize')return {protocolVersion:message.params.protocolVersion,capabilities:{tools:{},resources:{}},serverInfo:{name:'homer-synthetic-mcp',version:'1'}};if(message.method==='ping')return {};if(message.method==='tools/list')return {tools:[{name:'echo',description:'Synthetic local echo',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text'],additionalProperties:false}}]};if(message.method==='tools/call')return {content:[{type:'text',text:'synthetic:'+message.params.arguments.text}],isError:false};if(message.method==='resources/list')return {resources:[]};if(message.method==='resources/templates/list')return {resourceTemplates:[]};throw Error('unsupported');}
if(process.argv[1]?.endsWith('native-capability-mcp.mjs'))createInterface({input:process.stdin}).on('line',line=>{const m=JSON.parse(line);if(m.id===undefined)return;try{process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:m.id,result:handleMcp(m)})+'\n');}catch{process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:m.id,error:{code:-32601,message:'unsupported'}})+'\n');}});
